    public static ObjectNode encode(Request request){
        Objects.requireNonNull(request);ObjectNode r=StrictJson.object();r.put("expected_revision",PublicUnsigned64.canonical(request.expectedRevision(),request.method()==Method.CREATION_SELECTION?PublicUnsigned64.Minimum.ZERO:PublicUnsigned64.Minimum.ONE));
        switch(request){
            case InventoryPost v->r.put("expected_intent_sequence",PublicUnsigned64.canonical(v.expectedIntentSequence(),PublicUnsigned64.Minimum.ONE));
            case ArtifactRead v->r.put("artifact_id",v.artifactId());
            case PersonalPost v->{r.put("artifact_id",v.artifactId());r.put("expected_intent_sequence",PublicUnsigned64.canonical(v.expectedIntentSequence(),PublicUnsigned64.Minimum.ONE));}
            case PersonalSubmit v->{r.put("artifact_id",v.artifactId());r.put("desired_equipped",v.desiredEquipped());r.put("expected_slot_index",v.expectedSlotIndex());putOptionalId(r,"expected_replacing_artifact_id",v.expectedReplacingArtifactId());r.put("policy_positive",v.policyPositive());}
            case CharacterRead v->r.put("character_id",v.characterId());
            case SkillRead v->{r.put("character_id",v.characterId());r.put("skill",v.skill().key());}
            case RelicSite v->r.put("holy_site_id",v.holySiteId());
            case RelicPermissions v->{r.put("holy_site_id",v.holySiteId());putOptionalId(r,"artifact_id",v.artifactId());}
            case RelicPair v->{r.put("holy_site_id",v.holySiteId());r.put("artifact_id",v.artifactId());}
            case RelicSlot v->{r.put("holy_site_id",v.holySiteId());r.put("slot_index",v.slotIndex());r.put("desired_selected",v.desiredSelected());}
            case Enshrine v->{r.put("holy_site_id",v.holySiteId());r.put("artifact_id",v.artifactId());r.put("expected_effective_slot_index",v.expectedEffectiveSlotIndex());r.put("expected_replacing_empty",v.expectedReplacingEmpty());r.put("expected_preview_sha256",v.expectedPreviewSha256());putOptionalId(r,"expected_replacing_artifact_id",v.expectedReplacingArtifactId());}
            case Remove v->{r.put("holy_site_id",v.holySiteId());r.put("artifact_id",v.artifactId());r.put("expected_replacing_empty",v.expectedReplacingEmpty());r.put("expected_preview_sha256",v.expectedPreviewSha256());}
            case CreationSelection v->{r.put("artifact_id",v.artifactId());r.put("selected",v.selected());}
            case RevisionRequest ignored->{ }
        }return r;
    }
