        Optional<BigInteger> sequence=factsBody.has("intent_sequence")&&num(factsBody,"intent_sequence").signum()>0?Optional.of(number(factsBody,"intent_sequence",BigInteger.ONE,U64)):Optional.empty();
        Facts facts=new Facts(positive(factsBody,"available"),positive(factsBody,"once_intent_consumed"),positive(factsBody,"invoked")||positive(factsBody,"dispatch_invoked"),positive(factsBody,"needs_recovery")||positive(factsBody,"verification_pending"),positive(factsBody,"desired_window_observed")||positive(factsBody,"desired_inventory_state_observed"),sequence,positive(factsBody,"selection_postcondition_observed")||(m.kind()==Kind.CREATION_SELECTION&&positive(obj(required(body,"holy_site_creation_ui")),"selection_verified")),positive(factsBody,"native_dispatch_attempted"),positive(factsBody,"gameplay_command_may_have_been_queued"));
        NativePayload payload=new NativePayload(body);return switch(m.kind()){case PERSONAL_ITEM->new PersonalItemReply(m,facts,payload);case PERSONAL_ACTION->new PersonalActionReply(m,facts,payload);case INVENTORY_OPEN,INVENTORY_CLOSE->new InventoryReply(m,facts,payload);case KNIGHT->new KnightReply(m,facts,payload);case SKILLS->new SkillsReply(m,facts,payload);case RELIC_CONTEXT->new RelicContextReply(m,facts,payload);case RELIC_PERMISSIONS->new RelicPermissionsReply(m,facts,payload);case RELIC_ACTION_CONTEXT->new RelicActionContextReply(m,facts,payload);case RELIC_ACTION->new RelicActionReply(m,facts,payload);case CREATION_SELECTION->new CreationSelectionReply(m,facts,payload);};
