    public static ObjectNode encode(Reply reply){return publicProjection(reply);}
    /** Public presentation only. NativePayload retains exact native numeric tokens for ACK and historical comparisons. */
    public static ObjectNode publicProjection(Reply reply) {
        Objects.requireNonNull(reply);ObjectNode result=reply.payload().original();
        // These are exact top-level frame fields in the validated original family, never a recursive name rule.
        for(String key:List.of("snapshot_revision","capture_epoch","native_revision","pump_epoch"))
            if(result.has(key))publicCounter(result,key);
        switch(reply.method().kind()) {
            case PERSONAL_ITEM->publicItem(result);
            case PERSONAL_ACTION->{
                publicCounter(result,"intent_sequence");
                for(String prefix:List.of("before","after")){
                    publicCounter(result,prefix+"_native_revision");publicCounter(result,prefix+"_connection_generation");
                    JsonNode item=required(result,prefix);if(!item.isNull())publicItem(obj(item));
                }
            }
            case INVENTORY_OPEN,INVENTORY_CLOSE->publicInventory(result);
            case CREATION_SELECTION->{
                JsonNode context=required(obj(required(result,"holy_site_creation_ui")),"context");
                if(!context.isNull())publicCounter(obj(context),"capture_epoch");
            }
            case KNIGHT,SKILLS,RELIC_CONTEXT,RELIC_PERMISSIONS,RELIC_ACTION_CONTEXT,RELIC_ACTION->{ }
        }
        requireSafePublicIntegers(result,"$");return result;
    }
    private static void publicItem(ObjectNode item){publicCounter(item,"capture_epoch");}
    private static void publicInventory(ObjectNode window) {
        publicCounter(window,"intent_sequence");
        for(String key:List.of("current","before","after")){
            JsonNode raw=required(window,key);if(raw.isNull()){need(!key.equals("current"),"current inventory view cannot be null");continue;}
            ObjectNode view=obj(raw);for(String counter:List.of("native_revision","capture_epoch","connection_generation"))publicCounter(view,counter);
        }
    }
    private static void publicCounter(ObjectNode owner,String key) {
        JsonNode original=required(owner,key);BigInteger value;
        if(original.isIntegralNumber())value=StrictJson.integer(original,BigInteger.ZERO,U64);
        else value=PublicUnsigned64.parse(original,PublicUnsigned64.Minimum.ZERO,PublicUnsigned64.NumericInput.DECIMAL_ONLY);
        owner.put(key,PublicUnsigned64.canonical(value,PublicUnsigned64.Minimum.ZERO));
    }
    /** Validation only: an undeclared wide number cannot silently cross the public JSON boundary. */
    private static void requireSafePublicIntegers(JsonNode value,String path) {
        if(value.isIntegralNumber())need(value.bigIntegerValue().abs().compareTo(PublicUnsigned64.MAXIMUM_SAFE_NUMBER)<=0,
                "public integer requires an explicit typed decimal projection at "+path);
        else if(value.isObject())value.properties().forEach(field->requireSafePublicIntegers(field.getValue(),path+"."+field.getKey()));
        else if(value.isArray())for(int i=0;i<value.size();i++)requireSafePublicIntegers(value.get(i),path+"["+i+"]");
    }
